//! Owner lock segment only; no global Portal or purchase authority.
#![allow(dead_code)]
#[path = "../../support/rust-postgres.rs"] mod fixture;
use erpx_finance_server::public::portal_commerce_locks::lock_portal_finance_sources;
use erpx_platform_runtime_server::public::postgres::{MigrationTrack,load_migrations,migrate_database};
use sqlx::Connection;
#[tokio::test]
async fn fence_waits_for_real_writer_before_snapshot(){fixture::with_database(4,|pool|async move{
 let root=std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../../migrations/postgres");let files=load_migrations(root,MigrationTrack::HoldingWrite).await.unwrap();migrate_database(&pool,MigrationTrack::HoldingWrite,&files).await.unwrap();
 sqlx::raw_sql("INSERT INTO organization_nodes(id,kind,slug,display_name,parent_id,company_id,status,hierarchy_revision) VALUES('company','company','company','Company',NULL,'company','active',1),('branch','branch','branch','Branch','company','company','active',1); INSERT INTO finance_parties(id,company_id,kind,code,name,currency,status,version,created_at,updated_at) VALUES('party','company','customer','C1','Original','THB','active',1,0,0); INSERT INTO commerce_products(id,company_id,sku,name,price_minor) VALUES('product','company','P1','Product',100);").execute(pool.raw()).await.unwrap();let mut c=pool.raw().acquire().await.unwrap();assert!(lock_portal_finance_sources(&mut c).await.is_err());drop(c);
 let mut writer=pool.raw().begin().await.unwrap();let wp:i32=sqlx::query_scalar("SELECT pg_backend_pid()").fetch_one(&mut *writer).await.unwrap();sqlx::query("UPDATE finance_parties SET name='Committed' WHERE id='party'").execute(&mut *writer).await.unwrap();
 let other=pool.clone();let (send,recv)=tokio::sync::oneshot::channel();let reader=tokio::spawn(async move{let mut c=other.raw().acquire().await.unwrap();let pid:i32=sqlx::query_scalar("SELECT pg_backend_pid()").fetch_one(&mut *c).await.unwrap();send.send(pid).unwrap();let mut tx=c.begin_with("BEGIN ISOLATION LEVEL SERIALIZABLE").await.unwrap();lock_portal_finance_sources(&mut tx).await.unwrap();let n:i64=sqlx::query_scalar("SELECT count(*) FROM pg_locks WHERE pid=pg_backend_pid() AND granted AND mode='ShareRowExclusiveLock' AND relation=ANY(ARRAY['finance_invoices'::regclass,'finance_journals'::regclass,'finance_journal_lines'::regclass,'finance_book_postings'::regclass,'finance_payments'::regclass,'finance_allocations'::regclass,'finance_refund_obligations'::regclass,'money_transaction_snapshots'::regclass])").fetch_one(&mut *tx).await.unwrap();assert_eq!(n,8);let n:i64=sqlx::query_scalar("SELECT count(*) FROM pg_locks WHERE pid=pg_backend_pid() AND granted AND mode='ShareLock' AND relation=ANY(ARRAY['finance_parties'::regclass,'finance_charts'::regclass,'finance_accounts'::regclass,'finance_sales_defaults'::regclass,'finance_periods'::regclass,'finance_book_rules'::regclass,'finance_book_account_mappings'::regclass,'finance_dimension_definitions'::regclass,'finance_dimension_values'::regclass,'company_money_settings'::regclass,'company_currency_scales'::regclass,'company_fx_rates'::regclass,'finance_supplier_instructions'::regclass])").fetch_one(&mut *tx).await.unwrap();assert_eq!(n,13); let value:String=sqlx::query_scalar("SELECT name FROM finance_parties WHERE id='party'").fetch_one(&mut *tx).await.unwrap();tx.rollback().await.unwrap();value});
 let pid=recv.await.unwrap();let mut blocked=false;for _ in 0..200{blocked=sqlx::query_scalar("SELECT $1=ANY(pg_blocking_pids($2))").bind(wp).bind(pid).fetch_one(pool.raw()).await.unwrap();if blocked{break;}tokio::time::sleep(std::time::Duration::from_millis(10)).await;}assert!(blocked,"owner fence must wait for writer");writer.commit().await.unwrap();assert_eq!(tokio::time::timeout(std::time::Duration::from_secs(5),reader).await.unwrap().unwrap(),"Committed");
}).await;}
